<div class="page-head"><div><span class="eyebrow">РУЛЕТКА</span><h1><?=e($roulette['title'])?></h1><p class="muted"><?=e($roulette['description'])?></p></div></div>
<div class="roulette-wrap"><div class="roulette-stage"><div class="roulette-pointer">▼</div><canvas id="wheel" width="560" height="560"></canvas><button id="spin" class="spin-button">КРУТИТЬ</button></div><div id="roulette-result" class="card roulette-result">Натисніть «Крутити»</div></div>
<script>
(()=>{const segs=<?=json_encode($segments,JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT)?>;const c=document.getElementById('wheel'),ctx=c.getContext('2d'),spin=document.getElementById('spin'),out=document.getElementById('roulette-result');const cx=280,cy=280,r=245;let angle=0,busy=false;const imgs={};
segs.forEach((s,i)=>{if(s.image_path){const im=new Image();im.src='<?=base_url()?>/'+s.image_path;imgs[i]=im;}});
function draw(){ctx.clearRect(0,0,560,560);const total=segs.reduce((a,s)=>a+Number(s.weight||1),0);let a=angle-Math.PI/2;segs.forEach((s,i)=>{const da=Math.PI*2*(Number(s.weight||1)/total);ctx.beginPath();ctx.moveTo(cx,cy);ctx.arc(cx,cy,r,a,a+da);ctx.closePath();ctx.fillStyle=`hsl(${(i*360/segs.length)%360} 75% 70%)`;ctx.fill();ctx.strokeStyle='#fff';ctx.lineWidth=4;ctx.stroke();ctx.save();ctx.translate(cx,cy);ctx.rotate(a+da/2);ctx.fillStyle='#172033';ctx.font='700 15px system-ui';ctx.textAlign='center';ctx.fillText(s.label.slice(0,22),r*.62,5);if(imgs[i]&&imgs[i].complete){ctx.drawImage(imgs[i],r*.48,-35,70,70);}ctx.restore();a+=da;});ctx.beginPath();ctx.arc(cx,cy,54,0,Math.PI*2);ctx.fillStyle='#fff';ctx.fill();ctx.stroke();}
function pick(){const total=segs.reduce((a,s)=>a+Number(s.weight||1),0);let x=Math.random()*total;for(let i=0;i<segs.length;i++){x-=Number(segs[i].weight||1);if(x<=0)return segs[i];}return segs.at(-1)}
function go(){if(busy||!segs.length)return;busy=true;spin.disabled=true;const winner=pick();let target=0,total=segs.reduce((a,s)=>a+Number(s.weight||1),0),idx=segs.indexOf(winner);for(let i=0;i<idx;i++)target+=Number(segs[i].weight||1);target+=(Number(winner.weight||1)/2);const sector=target/total*Math.PI*2;const turns=Math.PI*2*(5+Math.floor(Math.random()*3));const start=angle;const final=turns-sector;const t0=performance.now(),dur=4300;function frame(t){const p=Math.min(1,(t-t0)/dur),ease=1-Math.pow(1-p,4);angle=start+(final-start)*ease;draw();if(p<1)requestAnimationFrame(frame);else{angle=angle%(Math.PI*2);out.innerHTML='<b>Випало:</b> '+winner.label;if(winner.image_path)out.innerHTML+='<br><img class="roulette-result-image" src="<?=base_url()?>/'+winner.image_path+'">';busy=false;spin.disabled=false;}}requestAnimationFrame(frame)}spin.onclick=go;segs.forEach((_,i)=>imgs[i]?.addEventListener('load',draw));draw();})();</script>